  ar: { "arc.cephe_cagri.t":"نداء الجهاد", "arc.cephe_cagri.b":"تُقرَع الطبول على الثغور؛ سيفك مطلوب.", "arc.kervan_komplo.t":"مؤامرة القافلة", "arc.kervan_komplo.b":"حمولة قافلةٍ تُخفي أكثر ممّا تبدو.", "arc.tekke_sirri.t":"سرّ التكية", "arc.tekke_sirri.b":"تقواك فتحت لك باب تكيّة درويش.", "arc.yasak_ask.t":"حبٌّ على كلّ لسان", "arc.yasak_ask.b":"غراميّةٌ صارت حديث الديار.", "arc.saray_entrika.t":"مكيدة القصر", "arc.saray_entrika.b":"لا يَدَع العرشُ راحةً يومًا واحدًا؛ والظلال تتحرّك.", "arc.miras_kavgasi.t":"نزاع الميراث", "arc.miras_kavgasi.b":"وأنت بعدُ حيّ، تنازَع أبناؤك على نصيبهم.", "arc.lonca_secimi.t":"انتخاب النقابة", "arc.lonca_secimi.b":"اسمك مطروحٌ لمنصب كتخدا النقابة.", "arc.kayip_kardes.t":"الأخ المفقود", "arc.kayip_kardes.b":"ظهر أثرُ قريبٍ ضاع منذ سنين.", "arc.namus_duello.t":"مسألة شرف", "arc.namus_duello.b":"كلمتك تُذكَر بالمروءة؛ وقد داسها أحدهم.", "arc.sifa_supheli.t":"الوباء والشكّ", "arc.sifa_supheli.b":"شفاؤك يجلب الدعاء والتُّهمة معًا." },
