// Yeni oyun açılış sinematiği (%c=çocuk, %n=ad).
const NG: Record<Lang, Dict> = {
  tr: { "ng.childGirl":"bir kız çocuğu","ng.childBoy":"bir oğlan çocuğu","ng.cine1":"1247. Anadolu — küllerin ve közün diyarı. Sınır boylarında beylikler yükselir, kervanlar tozlu yollarda yürür, her ocakta bir hikâye pişer.","ng.cine2":"Karlı bir kış gecesi, küçük bir köy evinde %c olarak gözlerini dünyaya açtın. Sana %n adını verdiler.","ng.cine3":"Önünde koca bir ömür var: ekmeğini kazanacak, seveceksin, savaşacak, belki bir hanedan kuracaksın. Küllerin altındaki köz, senin hikâyenle alevlenecek." },
  en: { "ng.childGirl":"a baby girl","ng.childBoy":"a baby boy","ng.cine1":"1247, Anatolia — a land of ashes and embers. Beyliks rise along the frontier, caravans trudge dusty roads, and in every hearth a story simmers.","ng.cine2":"On a snowy winter's night, in a small village home, you opened your eyes to the world as %c. They named you %n.","ng.cine3":"A whole life lies before you: you will earn your bread, love, fight, perhaps found a dynasty. The ember beneath the ashes will blaze with your story." },
  es: { "ng.childGirl":"una niña","ng.childBoy":"un niño","ng.cine1":"1247, Anatolia — una tierra de cenizas y brasas. Los beylicatos se alzan en la frontera, las caravanas recorren caminos polvorientos, y en cada hogar se cuece una historia.","ng.cine2":"En una noche nevada de invierno, en una pequeña casa de aldea, abriste los ojos al mundo como %c. Te llamaron %n.","ng.cine3":"Toda una vida te espera: ganarás tu pan, amarás, lucharás, quizá fundes una dinastía. La brasa bajo las cenizas arderá con tu historia." },
  pt: { "ng.childGirl":"uma menina","ng.childBoy":"um menino","ng.cine1":"1247, Anatólia — uma terra de cinzas e brasas. Os beilhados erguem-se na fronteira, as caravanas percorrem estradas poeirentas, e em cada lar uma história ferve.","ng.cine2":"Numa noite nevada de inverno, numa pequena casa de aldeia, abriste os olhos para o mundo como %c. Deram-te o nome de %n.","ng.cine3":"Uma vida inteira te espera: ganharás o teu pão, amarás, lutarás, talvez fundes uma dinastia. A brasa sob as cinzas arderá com a tua história." },
  ar: { "ng.childGirl":"طفلة","ng.childBoy":"طفلًا","ng.cine1":"عام 1247، الأناضول — ديار الرماد والجمر. تنهض الإمارات على الثغور، وتسير القوافل في الدروب المغبرّة، وفي كل موقد تنضج حكاية.","ng.cine2":"في ليلة شتاء مثلجة، في بيت قرويّ صغير، فتحت عينيك على الدنيا %c. وأسموك %n.","ng.cine3":"أمامك عمر بأكمله: ستكسب خبزك، وتحبّ، وتقاتل، وربما تؤسّس سلالة. الجمرة تحت الرماد ستتّقد بحكايتك." },
  ru: { "ng.childGirl":"девочкой","ng.childBoy":"мальчиком","ng.cine1":"1247 год, Анатолия — край пепла и углей. На рубежах поднимаются бейлики, караваны бредут пыльными дорогами, и в каждом очаге зреет своя история.","ng.cine2":"Снежной зимней ночью, в маленьком деревенском доме, ты открыл глаза миру %c. Тебя нарекли %n.","ng.cine3":"Впереди целая жизнь: будешь добывать хлеб, любить, сражаться, быть может, основаешь династию. Уголёк под пеплом разгорится твоей историей." },
};
